SELECT
*
FROM login_fail



        AND INSTR(login_fail.login_name,#{queryForm.loginName})



        AND login_fail.lock_flag = #{queryForm.lockFlag}



        AND DATE_FORMAT(login_fail.login_lock_begin_time, '%Y-%m-%d') >= #{queryForm.loginLockBeginTimeBegin}


        AND DATE_FORMAT(login_fail.login_lock_begin_time, '%Y-%m-%d') <= #{queryForm.loginLockBeginTimeEnd}


order by login_fail.update_time desc

